'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const n = input[idx++];
const graph = Array.from({ length: n }, () => []);

for (let i = 0; i < n - 1; i++) {
  const x = input[idx++] - 1;
  const y = input[idx++] - 1;
  graph[x].push(y);
  graph[y].push(x);
}

function bfs(start, withParent = false) {
  const dist = new Int32Array(n);
  dist.fill(-1);
  const parent = withParent ? new Int32Array(n) : null;
  const queue = new Int32Array(n);
  let head = 0;
  let tail = 0;

  queue[tail++] = start;
  dist[start] = 0;
  if (withParent) parent[start] = start;

  let farthest = start;

  while (head < tail) {
    const node = queue[head++];
    if (dist[node] > dist[farthest]) farthest = node;

    for (const next of graph[node]) {
      if (dist[next] !== -1) continue;
      dist[next] = dist[node] + 1;
      if (withParent) parent[next] = node;
      queue[tail++] = next;
    }
  }

  return { farthest, dist, parent };
}

const endpointA = bfs(0).farthest;
const result = bfs(endpointA, true);
const endpointB = result.farthest;
const diameter = result.dist[endpointB];

const path = [];
for (let node = endpointB; node !== endpointA; node = result.parent[node]) {
  path.push(node);
}
path.push(endpointA);
path.reverse();

const stackNode = new Int32Array(n);
const stackParent = new Int32Array(n);
const stackDepth = new Int32Array(n);

function countAtDepth(center, blocked, targetDepth) {
  let total = 0;

  for (const neighbor of graph[center]) {
    if (neighbor === blocked) continue;

    let top = 0;
    stackNode[top] = neighbor;
    stackParent[top] = center;
    stackDepth[top++] = 1;

    while (top > 0) {
      const node = stackNode[--top];
      const parent = stackParent[top];
      const depth = stackDepth[top];

      if (depth === targetDepth) {
        total++;
        continue;
      }

      for (const next of graph[node]) {
        if (next === parent) continue;
        stackNode[top] = next;
        stackParent[top] = node;
        stackDepth[top++] = depth + 1;
      }
    }
  }

  return total;
}

let ways = 0;

if (diameter % 2 === 0) {
  const center = path[diameter / 2];
  const targetDepth = diameter / 2;
  let seen = 0;

  for (const neighbor of graph[center]) {
    const count = countAtDepth(center, neighbor, targetDepth);
    ways += seen * count;
    seen += count;
  }
} else {
  const leftCenter = path[Math.floor(diameter / 2)];
  const rightCenter = path[Math.floor(diameter / 2) + 1];
  const targetDepth = Math.floor(diameter / 2);

  const leftCount = countAtDepth(leftCenter, rightCenter, targetDepth);
  const rightCount = countAtDepth(rightCenter, leftCenter, targetDepth);
  ways = leftCount * rightCount;
}

console.log(diameter + 1);
console.log(ways);
